package net.officefloor.hq.app.setting;

/**
 * A user's role on a sheet: a clerk (any name not given another role) settles only within the clerk limit; a steward
 * settles anything; a viewer sees everything and changes nothing.
 */
public enum Role {
    CLERK, STEWARD, VIEWER;

    /** The role as it is typed and shown: lower case. */
    public String label() {
        return name().toLowerCase();
    }

    /** The role with this label (case and outer spaces ignored), or null. */
    public static Role of(String label) {
        String wanted = label == null ? "" : label.trim();
        for (Role role : values()) {
            if (role.label().equalsIgnoreCase(wanted)) {
                return role;
            }
        }
        return null;
    }
}
package net.officefloor.hq.app.setting;

/** The role a user name has on a sheet. */
public record UserRole(String sheetId, String user, Role role) {
}
package net.officefloor.hq.app.setting;

import jakarta.validation.Valid;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidateRoleRequest {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody @Valid RoleRequest request,
            Out<UserRole> role) throws InvalidSettingException {
        String user = request.user() == null ? "" : request.user().trim();
        if (user.isEmpty()) {
            throw new InvalidSettingException("A user name is required.");
        }
        Role found = Role.of(request.role());
        if (found == null) {
            throw new InvalidSettingException("The role must be clerk, steward or viewer.");
        }
        role.set(new UserRole(sheetId, user, found));
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.Size;

/** A role as the form submits it: the user name and the role (clerk, steward or viewer). */
public record RoleRequest(@Size(max = 100) String user, @Size(max = 30) String role) {
}
package net.officefloor.hq.app.setting;

import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Refuses (400) any change by a viewer on the sheet: it runs first, so a refused change writes nothing. */
public class CheckNotViewer {
    public void check(@PathVariable("sheetId") String sheetId, @RequestParam("user") String user,
            SettingRepository settings) throws ViewerRefusedException {
        if (settings.find(sheetId).roleOf(user) == Role.VIEWER) {
            throw new ViewerRefusedException("A viewer cannot change the sheet.");
        }
    }
}
import { useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { ROLES, settingsKey, useSettings } from './settings';
import type { Settings, UserRole } from './settings';
import { useOneAtATime } from '../../query/useOneAtATime';

const EMPTY: UserRole = { user: '', role: '' };

// The roles given to user names on the sheet (any other name is a clerk) and the form that gives one.
export function Roles() {
  const [user] = useCurrentUser();
  const [sheet] = useCurrentSheet();
  const roles = useSettings().data?.roles ?? [];
  const [form, setForm] = useState<UserRole>(EMPTY);
  const [error, setError] = useState('');
  const queryClient = useQueryClient();
  const once = useOneAtATime();

  const save = useMutation({
    mutationFn: (input: UserRole) =>
      putJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/roles?user=${encodeURIComponent(user)}`, input),
    onSuccess: async (saved) => {
      setForm(EMPTY);
      setError('');
      queryClient.setQueryData(settingsKey(sheet), saved);
      await queryClient.invalidateQueries({ queryKey: settingsKey(sheet) });
    },
    onError: () => setError('That role could not be set.'),
  });

  if (!user || !sheet) return null;

  const submit = (e: FormEvent) => {
    e.preventDefault();
    setError('');
    const name = form.user.trim();
    const role = form.role.trim().toLowerCase();
    if (name === '') {
      setError('Type a user name.');
      return;
    }
    if (!ROLES.includes(role)) {
      setError(`Type a role: ${ROLES.join(' or ')}.`);
      return;
    }
    once(() => save.mutateAsync({ user: name, role }));
  };

  const change = (patch: Partial<UserRole>) => {
    setForm((f) => ({ ...f, ...patch }));
    setError('');
  };

  return (
    <section data-testid="roles">
      <table data-testid="role-list">
        <thead>
          <tr>
            <th>User</th>
            <th>Role</th>
          </tr>
        </thead>
        <tbody>
          {roles.map((r) => (
            <tr key={r.user} data-testid={`role-row-${r.user}`}>
              <td data-testid="role-user">{r.user}</td>
              <td data-testid="role-value">{r.role}</td>
            </tr>
          ))}
        </tbody>
      </table>
      <form onSubmit={submit} data-testid="role-form">
        <input
          data-testid="role-form-user"
          placeholder="User name"
          value={form.user}
          onChange={(e) => change({ user: e.target.value })}
        />
        <input
          data-testid="role-form-role"
          placeholder={`Role (${ROLES.join(' or ')})`}
          list="role-options"
          value={form.role}
          onChange={(e) => change({ role: e.target.value })}
        />
        <datalist id="role-options">
          {ROLES.map((r) => (
            <option key={r} value={r} />
          ))}
        </datalist>
        <button type="submit" data-testid="role-form-submit" disabled={save.isPending}>
          Set role
        </button>
        {error && <span data-testid="role-form-error">{error}</span>}
      </form>
    </section>
  );
}
